from itertools import product
xs=[25,31,37,43,49,55]; ys=[20,26,32,38,44,50]
valid={(x,y) for x in [43,49,55] for y in [20,26,32,38]} | {(x,y) for x in [25,31,37,43,49] for y in [44,50]}
start=frozenset({(49,38),(55,38),(25,44),(37,44),(43,44)})
def moves(s):
 for x,y in s:
  for dx,dy in [(2,0),(-2,0),(0,2),(0,-2)]:
   mid=(x+dx//2*6,y+dy//2*6); dst=(x+dx*6,y+dy*6)
   if mid in s and dst in valid and dst not in s:
    yield (x,y),dst,frozenset((s-{(x,y),mid})|{dst})
from collections import deque
q=deque([(start,[])]); seen={start}; sol=None
while q:
 s,path=q.popleft()
 if len(s)==1: sol=path;break
 for a,b,t in moves(s):
  if t not in seen: seen.add(t);q.append((t,path+[(a,b)]))
print(sol)

