def allmoves(s):
 # jumps
 yield from moves3(s)
 # merges adjacent (and perhaps any e)
 for a in s:
  for b in s:
   if a!=b and abs(a[0]-b[0])+abs(a[1]-b[1])==6:
    yield a,b,frozenset((s-{a}))
q=deque([(start,[])]);seen={start};sol=None
while q:
 s,path=q.popleft()
 if len(s)==1:sol=path;break
 for a,b,t in allmoves(s):
  if t not in seen:seen.add(t);q.append((t,path+[(a,b)]))
print(sol)

def legalmoves(s):
 jumps=list(moves3(s))
 jump_sources={a for a,b,t in jumps}
 yield from jumps
 for a in jump_sources:
  for b in s:
   if a!=b:
    yield a,b,frozenset(s-{a})
q=deque([(start,[])]);seen={start};sol=None
while q:
 s,path=q.popleft()
 if len(s)==1:sol=path;break
 for a,b,t in legalmoves(s):
  if t not in seen:seen.add(t);q.append((t,path+[(a,b)]))
print(sol, len(seen))

